const money = (n: number) => "$" + n.toLocaleString("en-US");
const feeText = (fees: Fees, name: string) => {
  const f = fees[name] ?? {};
  const p = [f.NGN && "₦" + Number(f.NGN).toLocaleString(), f.USD && money(Number(f.USD))].filter(Boolean);
  return p.length ? p.join(" / ") : "Fee to be announced";
};
async function api<T = unknown>(path: string, method = "GET", body?: unknown): Promise<T> {
  const r = await fetch("/api" + path, { method, credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: body ? JSON.stringify(body) : undefined });
  const j: unknown = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error((j as { error?: string }).error || "Request failed");
  return j as T;
}
const readFile = (f: File) => new Promise<{ name: string; data: string }>((res) => { const x = new FileReader(); x.onload = () => res({ name: f.name, data: String(x.result).split(",")[1] ?? "" }); x.readAsDataURL(f); });
const ROUTES: Route[] = ["home", "about", "membership", "programmes", "foundation", "contact", "apply", "portal", "admin", "legal", "login"];
function useRoute(): Route {
  const get = (): Route => { const h = location.hash.slice(1) as Route; return ROUTES.includes(h) ? h : "home"; };
  const [r, setR] = useState<Route>(get);
  useEffect(() => { const f = () => { setR(get()); window.scrollTo(0, 0); }; window.addEventListener("hashchange", f); return () => window.removeEventListener("hashchange", f); }, []);
  return r;
}

