function Auth({ onDone }: { onDone: () => Promise<void> }) {
  const [mode, setMode] = useState<"login" | "register">("login"); const [f, setF] = useState({ name: "", email: "", password: "" }); const [err, setErr] = useState("");
  const set = (k: keyof typeof f) => (e: ChangeEvent<HTMLInputElement>) => setF({ ...f, [k]: e.target.value });
  const go = async () => { try { await api(mode === "login" ? "/login" : "/register", "POST", f); await onDone(); } catch (e) { setErr((e as Error).message); } };
  return <Section><div className={cx(card, "mx-auto max-w-md")}><h1 className="font-serif text-2xl font-bold">{mode === "login" ? "Log in" : "Create your account"}</h1><p className="mb-4 mt-1 text-sm text-neutral-500">Applicants and members use the same account.</p>
    {mode === "register" && <Label text="Full name"><input className={input} value={f.name} onChange={set("name")} autoComplete="name" /></Label>}
    <Label text="Email"><input type="email" className={input} value={f.email} onChange={set("email")} autoComplete="email" /></Label>
    <Label text={mode === "register" ? "Password (10+ characters)" : "Password"}><input type="password" className={input} value={f.password} onChange={set("password")} autoComplete={mode === "login" ? "current-password" : "new-password"} onKeyDown={(e) => e.key === "Enter" && void go()} /></Label>
    {err && <p className="mb-3 text-sm font-medium text-crimson-600" role="alert">{err}</p>}<button className={btnP} onClick={() => void go()}>{mode === "login" ? "Log in" : "Create account"}</button>
    <p className="mt-4 text-sm">{mode === "login" ? "New applicant?" : "Already registered?"} <button className="font-medium text-crimson underline dark:text-red-300" onClick={() => { setMode(mode === "login" ? "register" : "login"); setErr(""); }}>{mode === "login" ? "Create an account" : "Log in"}</button></p></div></Section>;
}
function Apply({ S, reload }: { S: AppState; reload: () => Promise<void> }) {
  const [step, setStep] = useState(1); const [err, setErr] = useState(""); const [busy, setBusy] = useState(false);
  const [f, setF] = useState<Form>({ cat: CATEGORIES[0].name, name: "", email: "", country: "", qual: "", inst: "", role: "", bio: "", files: [], dc: [false, false, false, false] });
  const cat = catOf(f.cat)!; const text = (k: keyof Form) => (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setF({ ...f, [k]: e.target.value });
  const next = () => { setErr(""); if (step === 2 && (!f.name || !EMAIL.test(f.email))) return setErr("Enter your full name and a valid email address."); if (step === 4 && f.dc.some((x) => !x)) return setErr("All declarations must be accepted."); setStep(step + 1); };
  const submit = async () => { setBusy(true); try { const docs = await Promise.all(f.files.map(readFile)); const { files: _f, dc: _d, ...rest } = f; void _f; void _d; await api("/apps", "POST", { ...rest, docs }); await reload(); location.hash = "portal"; } catch (e) { setErr((e as Error).message); setBusy(false); } };
  const labels = ["Category", "Details", "Documents", "Declarations", "Review"];
  return (<><Band eyebrow="Apply" title="Membership application" sub="Complete the steps below. Your application is assessed manually by the Membership and Credentials Assessment Committee." />
    <Section><div className="mb-6 flex flex-wrap gap-2">{labels.map((l, i) => <span key={l} className={cx("rounded-full px-3 py-1 text-xs font-medium", step === i + 1 ? "bg-crimson text-white" : step > i + 1 ? "bg-red-100 text-crimson" : "bg-neutral-100 text-neutral-500 dark:bg-neutral-800")}>{i + 1}. {l}</span>)}</div>
      <div className={cx(card, "max-w-2xl")}>
        {step === 1 && <><Label text="Membership category"><select className={input} value={f.cat} onChange={(e) => setF({ ...f, cat: e.target.value })}>{CATEGORIES.map((c) => <option key={c.name}>{c.name}</option>)}</select></Label>
          <ul className="mb-4 list-disc space-y-1 pl-5 text-sm text-neutral-600 dark:text-neutral-300">{cat.criteria.map((x) => <li key={x}>{x}</li>)}</ul><p className="mb-4 text-sm font-semibold">Fee: {feeText(S.fees, cat.name)}</p>
          {cat.nominationOnly && <p className="mb-4 rounded-lg bg-neutral-100 p-3 text-sm dark:bg-neutral-700">Honorary Fellowship is by nomination only. Please use the contact form to nominate a candidate. The fee applies only if the nomination is approved.</p>}</>}
        {step === 2 && <>{([["name", "Full legal name"], ["email", "Email address"], ["country", "Country"], ["qual", "Highest qualification"], ["inst", "Awarding institution / doctoral programme"], ["role", "Current role & organisation"]] as [keyof Form, string][]).map(([k, l]) => <Label key={k} text={l}><input type={k === "email" ? "email" : "text"} className={input} value={String(f[k])} onChange={text(k)} /></Label>)}
          <Label text="Short biography"><textarea rows={3} className={input} value={f.bio} onChange={text("bio")} /></Label></>}
        {step === 3 && <><Label text="Supporting evidence (certificates, ID, CV)"><input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.doc,.docx" className={input} onChange={(e) => setF({ ...f, files: Array.from(e.target.files ?? []).slice(0, 5) })} /></Label><p className="rounded-lg bg-neutral-100 p-3 text-xs dark:bg-neutral-700">Accepted: PDF, JPG, PNG, DOC, DOCX. Up to 5 files, 5 MB each. Files are stored privately and visible only to you and authorised assessors.</p></>}
        {step === 4 && <div className="space-y-3">{["the IFDSP Constitution", "the Code of Ethics", "the Privacy Notice", "that all information is accurate"].map((t, i) => <label key={t} className="flex gap-2 text-sm"><input type="checkbox" checked={f.dc[i]} onChange={(e) => setF({ ...f, dc: f.dc.map((v, j) => (j === i ? e.target.checked : v)) })} />I accept {t}</label>)}</div>}
        {step === 5 && <><p className="text-sm text-neutral-500">Category</p><p className="font-semibold">{f.cat}</p><p className="mt-3 text-sm text-neutral-500">Fee</p><p className="font-serif text-2xl font-bold text-crimson dark:text-red-300">{feeText(S.fees, f.cat)}</p>
          <p className="mt-3 rounded-lg bg-neutral-100 p-3 text-xs dark:bg-neutral-700">Online payment is not yet available. The Secretariat will send payment instructions after your application is received. Payment never approves membership.</p></>}
        {err && <p className="mt-3 text-sm font-medium text-crimson-600" role="alert">{err}</p>}
        <div className="mt-6 flex gap-3">{step > 1 && <button className={btnO} onClick={() => setStep(step - 1)}>Back</button>}
          {step < 5 ? (cat.nominationOnly && step === 1 ? <a href="#contact" className={btnP}>Nominate a candidate</a> : <button className={btnP} onClick={next}>Continue</button>) : <button className={btnP} disabled={busy} onClick={() => void submit()}>{busy ? "Submitting…" : "Submit application"}</button>}</div>
      </div></Section></>);
}
function Portal({ S, reload }: { S: AppState; reload: () => Promise<void> }) {
  const [resp, setResp] = useState(""); const a = [...S.apps].filter((x) => x.owner === S.user?.id).pop();
  if (!a) return <><Band eyebrow="My Portal" title="Welcome" /><Section><p>No application yet. <a className="text-crimson underline" href="#apply">Start one</a>.</p></Section></>;
  const idx = a.status === "Approved" ? 2 : 1; const flow = ["Submitted", "Under review", "Approved"];
  const send = () => api(`/apps/${a.id}/respond`, "POST", { text: resp }).then(reload);
  return (<><Band eyebrow="My Portal" title={`Application ${a.id}`} /><Section><div className="grid gap-6 lg:grid-cols-3">
    <div className={cx(card, "lg:col-span-2")}><div className="flex flex-wrap items-center gap-2"><Tag tone="bg-crimson text-white">{a.status}</Tag><span className="text-sm text-neutral-500">{a.cat}</span></div>
      <div className="my-6 flex items-center">{flow.map((s, i) => <div key={s} className="flex flex-1 items-center"><span className={cx("flex h-8 w-8 items-center justify-center rounded-full text-xs font-bold", i <= idx ? "bg-crimson text-white" : "bg-neutral-200 text-neutral-500")}>{i + 1}</span><span className="ml-2 text-xs">{s}</span>{i < 2 && <span className={cx("mx-2 h-0.5 flex-1", i < idx ? "bg-crimson" : "bg-neutral-200")} />}</div>)}</div>
      {a.status === "Information required" && <div className="rounded-lg border-l-4 border-crimson bg-red-50 p-4 text-sm text-ink"><b>Action needed:</b> {a.msgs[a.msgs.length - 1]}<input className={cx(input, "mt-2")} placeholder="Your response" value={resp} onChange={(e) => setResp(e.target.value)} /><button className={btnP} onClick={() => void send()}>Send response</button></div>}
      {a.status === "Rejected" && <p className="text-sm">Decision: {a.msgs[a.msgs.length - 1]}</p>}
      <h3 className="mt-4 font-semibold">Membership fee</h3><p className="text-sm">Fee: <b>{feeText(S.fees, a.cat)}</b></p><p className="mt-2 text-sm text-neutral-600 dark:text-neutral-300">Online payment is not yet available. The Secretariat will contact you with payment instructions.</p></div>
    <div>{a.status === "Approved" ? <div className="rounded-2xl bg-gradient-to-br from-crimson to-crimson-900 p-6 text-white shadow-lg ring-1 ring-gold/60"><p className="text-xs tracking-widest text-red-200">IFDSP · MEMBER</p><p className="mt-6 font-serif text-2xl font-bold">{a.name}</p><p className="text-sm">{catOf(a.cat)?.code} · {a.cat}</p><p className="mt-6 text-xs text-red-200">ID {a.mid}</p></div> : <div className={cx(card, "text-sm")}>No membership card or designation is issued until an authorised assessor approves your credentials.</div>}</div></div></Section></>);
}
function Admin({ S, reload }: { S: AppState; reload: () => Promise<void> }) {
  const [sel, setSel] = useState<string | null>(null); const [msg, setMsg] = useState(""); const a = S.apps.find((x) => x.id === sel);
  const th = "px-3 py-2 text-left text-xs font-semibold uppercase text-crimson dark:text-red-300";
  const decide = (status: Status) => { if (status !== "Approved" && !msg) return alert("Please enter a message or reason."); void api(`/admin/apps/${sel}/decide`, "POST", { status, message: msg }).then(() => { setMsg(""); return reload(); }).catch((e: Error) => alert(e.message)); };
  const setFee = (category: string, currency: "USD" | "NGN", value: string) => { if ((S.fees[category]?.[currency] ?? "") !== value) void api("/admin/fees", "POST", { category, currency, value }).then(reload).catch((e: Error) => alert(e.message)); };
  return (<><Band eyebrow="Staff" title="Operations workspace" sub="Assessor decisions, administrator-managed fees and the audit trail." /><Section>
    <div className={cx(card, "overflow-x-auto")}><table className="w-full text-sm"><thead><tr><th className={th}>Ref</th><th className={th}>Applicant</th><th className={th}>Category</th><th className={th}>Status</th><th /></tr></thead><tbody>{S.apps.length ? S.apps.map((x) => <tr key={x.id} className="border-t dark:border-neutral-700"><td className="px-3 py-2">{x.id}</td><td className="px-3">{x.name}</td><td className="px-3">{x.cat}</td><td className="px-3">{x.status}</td><td><button className={cx(btnO, "!py-1")} onClick={() => setSel(x.id)}>Open</button></td></tr>) : <tr><td colSpan={5} className="px-3 py-6 text-center text-neutral-500">No applications yet.</td></tr>}</tbody></table></div>
    {a && <div className={cx(card, "mt-6")}><h3 className="font-semibold">{a.id} — {a.name}</h3><p className="mt-1 text-sm text-neutral-600 dark:text-neutral-300">{a.email} · {a.country}<br />{a.qual} — {a.inst}<br />{a.role}<br />Evidence: {a.docs.map((d) => <a key={d.id} className="mr-2 underline" href={"/api/files/" + d.id}>{d.name}</a>)}</p><p className="mt-2 text-sm">{a.bio}</p>{a.notes.map((n, i) => <p key={i} className="text-sm italic">{n}</p>)}
      <input className={cx(input, "mt-3")} placeholder="Message / reason for applicant" value={msg} onChange={(e) => setMsg(e.target.value)} /><div className="flex flex-wrap gap-2"><button className={btnO} onClick={() => decide("Information required")}>Request info</button><button className={btnP} onClick={() => decide("Approved")}>Approve</button><button className={btnO} onClick={() => decide("Rejected")}>Reject</button></div></div>}
    <h3 className="mb-3 mt-10 font-semibold">Fee configuration</h3><div className={cx(card, "overflow-x-auto")}><table className="w-full text-sm"><thead><tr><th className={th}>Category</th><th className={th}>USD</th><th className={th}>NGN</th></tr></thead><tbody>{CATEGORIES.map((c) => <tr key={c.name} className="border-t dark:border-neutral-700"><td className="px-3 py-1">{c.name}</td>{(["USD", "NGN"] as const).map((cu) => <td key={cu} className="px-3"><input type="number" min={0} className={cx(input, "!my-1 w-28")} defaultValue={S.fees[c.name]?.[cu] ?? ""} onBlur={(e) => setFee(c.name, cu, e.target.value)} /></td>)}</tr>)}</tbody></table></div>
    <h3 className="mb-3 mt-10 font-semibold">Audit log</h3><div className={cx(card, "space-y-1 text-xs")}>{S.audit.length ? S.audit.map((x, i) => <p key={i}>{x}</p>) : "No events."}</div></Section></>);
}
function Contact() {
  const [f, setF] = useState({ type: "General enquiry", name: "", email: "", msg: "" }); const [ok, setOk] = useState(false); const [err, setErr] = useState("");
  const set = (k: keyof typeof f) => (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => setF({ ...f, [k]: e.target.value });
  const send = () => { if (!f.name || !f.msg || !EMAIL.test(f.email)) return setErr("Please complete every field with a valid email address."); setErr(""); setOk(true); };
  const h = "font-semibold text-crimson dark:text-red-300";
  return (<><Band eyebrow="Contact" title="Get in touch" sub="Our International Secretariat and Nigeria operational office welcome your enquiries." /><Section><div className="grid gap-8 lg:grid-cols-3">
    <div className={cx(card, "space-y-5 text-sm")}><div><p className={h}>Registered office (headquarters)</p><p>{REG}</p></div><div><p className={h}>Operational office, Nigeria</p><p>{OPS}</p></div><div><p className={h}>Telephone</p><a className="underline" href="tel:+2348133044666">+234 813 304 4666</a></div><div><p className={h}>WhatsApp</p><a className="underline" href="https://wa.me/447824421377" rel="noopener">+44 7824 421377</a></div></div>
    <div className={cx(card, "lg:col-span-2")}>{ok ? <div role="status"><h3 className="font-serif text-2xl font-bold">Thank you, {f.name}</h3><p className="mt-2 text-sm">Your {f.type.toLowerCase()} has been recorded. (Demo: no email is sent until an email provider is connected.)</p></div> : <>
      <Label text="Enquiry type"><select className={input} value={f.type} onChange={set("type")}>{["General enquiry", "Membership enquiry", "Conference enquiry", "Institutional partnership", "Honorary Fellow nomination", "Chapter establishment request"].map((t) => <option key={t}>{t}</option>)}</select></Label>
      <Label text="Full name"><input className={input} value={f.name} onChange={set("name")} /></Label><Label text="Email"><input type="email" className={input} value={f.email} onChange={set("email")} /></Label><Label text="Message"><textarea rows={4} className={input} value={f.msg} onChange={set("msg")} /></Label>
      {err && <p className="mb-3 text-sm font-medium text-crimson-600" role="alert">{err}</p>}<button className={btnP} onClick={send}>Send enquiry</button></>}</div></div></Section></>);
}
function Legal() {
  const [t, setT] = useState(Object.keys(LEGAL)[0]);
  return (<><Band eyebrow="Legal" title="Privacy, terms & policies" /><Section><div className="flex flex-wrap gap-2">{Object.keys(LEGAL).map((k) => <button key={k} onClick={() => setT(k)} className={cx("rounded-full px-4 py-1.5 text-sm font-medium", t === k ? "bg-crimson text-white" : "bg-neutral-100 dark:bg-neutral-800")}>{k}</button>)}</div>
    <div className={cx(card, "mt-6 max-w-3xl")}><h2 className="font-serif text-2xl font-bold">{t}</h2><p className="mt-3 leading-relaxed">{LEGAL[t]}</p><p className="mt-4 text-sm text-neutral-500">Questions? <a href="#contact" className="underline">Contact the Secretariat</a>.</p><p className="mt-2 text-sm text-neutral-500">Registered office: {REG}. Operational office: {OPS}.</p></div></Section></>);
}

/* ================================= App root ================================= */
export default function App() {
  const route = useRoute(); const [S, setS] = useState<AppState>({ user: null, apps: [], fees: DEFAULT_FEES, audit: [] });
  const load = useCallback(async () => { try { const j = await api<AppState>("/state"); setS({ ...j, fees: { ...DEFAULT_FEES, ...j.fees } }); } catch { /* server offline: public pages still render */ } }, []);
  useEffect(() => { void load(); }, [load]);
  const logout = () => { void api("/logout", "POST").then(() => { setS((s) => ({ ...s, user: null, apps: [], audit: [] })); location.hash = "home"; }); };
  let page: ReactNode;
  if (["apply", "portal", "admin", "login"].includes(route) && !S.user) page = <Auth onDone={async () => { await load(); if (route === "login") location.hash = "portal"; }} />;
  else if (route === "login") page = <Portal S={S} reload={load} />;
  else if (route === "admin" && S.user?.role !== "admin") page = <Section><p>This area is for IFDSP administrators.</p></Section>;
  else switch (route) {
    case "home": page = <Home fees={S.fees} />; break;
    case "about": case "programmes": case "foundation": page = <ContentPage def={PAGES[route]} />; break;
    case "membership": page = <Membership S={S} />; break;
    case "apply": page = <Apply S={S} reload={load} />; break;
    case "portal": page = <Portal S={S} reload={load} />; break;
    case "admin": page = <Admin S={S} reload={load} />; break;
    case "contact": page = <Contact />; break;
    default: page = <Legal />;
  }
  return <div className="min-h-screen"><a href="#main" className="sr-only focus:not-sr-only focus:absolute focus:z-50 focus:bg-white focus:p-2">Skip to content</a><Header route={route} user={S.user} onLogout={logout} /><main id="main" key={route} className="page">{page}</main><Footer /></div>;
}
